import { useFormState, useFormStatus } from 'react-dom'

async function saveContactMessage(formData: FormData) {
  'use server'

  const name = formData.get('name')
  const email = formData.get('email')
  const message = formData.get('message')

  // Validate that all fields are provided.
  if (!name || typeof name !== 'string' || name.trim() === '') {
    return { error: 'Name is required.' }
  }
  if (!email || typeof email !== 'string' || email.trim() === '') {
    return { error: 'Email is required.' }
  }
  if (!message || typeof message !== 'string' || message.trim() === '') {
    return { error: 'Message is required.' }
  }

  // Simulate saving the contact message.
  console.log('Saving contact message:', { name, email, message })

  return { error: null, success: 'Thank you for your message! We will get back to you soon.' }
}

function SubmitButton() {
  const { pending } = useFormStatus()
  return (
    <button type="submit" disabled={pending}>
      {pending ? 'Sending...' : 'Send Message'}
    </button>
  )
}

export default function ContactForm() {
  const [state, formAction] = useFormState(saveContactMessage, {
    error: null,
    success: null,
  })

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="Your email" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Your message" required />
        </div>
        <SubmitButton />
        {state?.error && <p role="alert">{state.error}</p>}
        {state?.success && <p role="status">{state.success}</p>}
      </form>
    </div>
  )
}

